?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alumni Memories</title><link rel="stylesheet" href="css/font-awesome-4.7.0/css/font-awesome.min.css"><style>body{font:16px Arial;margin:0;background:#f4f7fb;color:#172b4d}.wrap{max-width:980px;margin:35px auto;padding:0 18px}.top{display:flex;justify-content:space-between;gap:16px}.card{background:#fff;border:1px solid #dce5ed;border-radius:12px;padding:22px;margin-top:18px}.back,button{background:#08766f;color:#fff;border:0;border-radius:7px;padding:10px 14px;text-decoration:none;font-weight:bold}label{display:block;font-size:13px;font-weight:bold;margin-top:12px}input{display:block;width:100%;box-sizing:border-box;margin-top:5px;padding:10px;border:1px solid #cdd8e4;border-radius:6px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:14px}.memory{border:1px solid #dce5ed;border-radius:10px;overflow:hidden}.memory img{width:100%;height:160px;object-fit:cover}.memory div{padding:10px}.memory p{margin:0 0 8px}.remove{background:#b42318;font-size:12px}@media(max-width:600px){.top{flex-direction:column}}</style></head><body><main class="wrap"><div class="top"><div><h1>Alumni memories</h1><p>Build the public “AYISEC Through the Years” memory wall.</p></div><div><a class="back" href="alumni-hub.php">Back to Alumni Hub</a> <a class="back" href="alumni.php">View public page</a></div></div><?php if($message){?><p class="card"><?php echo alumni_safe($message);?></p><?php }?><section class="card"><h2>Publish a memory</h2><form method="post" enctype="multipart/form-data"><label>Caption<input name="caption" required maxlength="180" placeholder="e.g. Class of 2018 Speech and Prize-Giving Day"></label><label>Year (optional)<input name="memoryyear" type="number" min="1950" max="2100"></label><label>Photo<input name="memoryimage" type="file" accept="image/jpeg,image/png,image/webp" required></label><p>JPG, PNG, or WebP; maximum 5 MB.</p><button name="upload_memory"><i class="fa fa-upload"></i> Publish memory</button></form></section><section class="card"><h2>Published memories</h2><div class="grid"><?php while($memories&&($row=mysqli_fetch_assoc($memories))){?><article class="memory"><img src="<?php echo alumni_safe($row['imagepath']);?>" alt=""><div><p><b><?php echo alumni_safe($row['caption']);?></b></p><small><?php echo alumni_safe($row['memoryyear']);?></small><form method="post"><input type="hidden" name="memoryid" value="<?php echo (int)$row['memoryid'];?>"><button class="remove" name="delete_memory" onclick="return confirm('Remove this memory?')">Remove</button></form></div></article><?php }?></div></section></main><script>document.querySelectorAll('form[method="post"]').forEach(function(f){var i=document.createElement('input');i.type='hidden';i.name='csrf';i.value='<?php echo alumni_safe(alumni_csrf_token()); ?>';f.appendChild(i);});</script></body></html>
